inline QList<DiagramTextItem*> texts(QETProject *project){QList<DiagramTextItem*> result;for(auto *d:project->diagrams())for(auto *i:d->items())if(auto *t=dynamic_cast<DiagramTextItem*>(i))if(!t->languageId16().isEmpty())result<<t;std::sort(result.begin(),result.end(),[](auto *a,auto *b){return a->languageId16()<b->languageId16();});return result;}
inline Element *owner(DiagramTextItem *text){for(auto *p=text->parentItem();p;p=p->parentItem())if(auto *e=dynamic_cast<Element*>(p))return e;return nullptr;}
inline bool descriptive(const QString &s){return QetLanguages16::isHumanPhrase(s); }
inline void scan(QETProject *project,QVariantMap &data){if(!data.contains("sourceLanguage"))data["sourceLanguage"]="en";if(!data.contains("activeLanguage"))data["activeLanguage"]=QetLanguages16::sourceLanguage(data);data["languages"]=QetLanguages16::languageCodes(data);auto entries=data.value("entries").toMap();for(auto *t:texts(project)){const QString source=t->toPlainText();if(source.trimmed().isEmpty())continue;QString id=t->languageId16();auto e=entries.value(id).toMap();if(e.isEmpty()){e={{"source",source},{"baseX",t->pos().x()},{"baseY",t->pos().y()},{"enabled",descriptive(source)},{"kind",owner(t)?"symbol text":"sheet text"}};if(auto *dynamic=dynamic_cast<DynamicElementTextItem*>(t))if(dynamic->textFrom()==DynamicElementTextItem::ElementInfo&&QStringList{"label","manufacturer_reference","manufacturer","quantity"}.contains(dynamic->infoName()))e["enabled"]=false;}else if(e.value("source").toString()!=source){e["previousSource"]=e.value("source");e["source"]=source;auto variants=e.value("variants").toMap();for(auto it=variants.begin();it!=variants.end();++it){auto v=it.value().toMap();v["stale"]=true;it.value()=v;}e["variants"]=variants;}if(QetLanguages16::blockId21(data,id).isEmpty()){const auto active=QetLanguages16::activeLanguage(data);auto vs=e.value("variants").toMap();auto v=vs.value(active).toMap();const QPointF expected(v.value("x",e.value("baseX")).toDouble(),v.value("y",e.value("baseY")).toDouble());if(QLineF(expected,t->pos()).length()>0.1){v["x"]=t->pos().x();v["y"]=t->pos().y();v["locked"]=true;vs[active]=v;e["variants"]=vs;}if(active==QetLanguages16::sourceLanguage(data)){e["baseX"]=t->pos().x();e["baseY"]=t->pos().y();}}e["context"]=QObject::tr("Sheet %1: %2").arg(project->diagrams().indexOf(t->diagram())+1).arg(owner(t)?owner(t)->elementInformations().value("label").toString():QObject::tr("free text"));entries[id]=e;}data["entries"]=entries;QetLanguageBlocks21::refreshSources(data);data=QetLanguagePositions21::capture(project,data);QetLanguages16::collectProjectPhrases(project,data);}
inline QVariantMap apply(QETProject *project,QVariantMap data,bool arrange=false){
 if(!project)return data;auto entries=data.value("entries").toMap();const QString lang=QetLanguages16::activeLanguage(data);project->setLanguageData(data);
 for(auto *text:texts(project)){
  auto e=entries.value(text->languageId16()).toMap();if(e.isEmpty())continue;const auto effective=QetLanguages16::effectiveId21(data,text->languageId16());auto target=entries.value(effective).toMap();auto v=target.value("variants").toMap().value(lang).toMap();
  const bool source=lang==QetLanguages16::sourceLanguage(data);text->setPos(source?e.value("baseX",text->pos().x()).toDouble():v.value("x",e.value("baseX",text->pos().x())).toDouble(),source?e.value("baseY",text->pos().y()).toDouble():v.value("y",e.value("baseY",text->pos().y())).toDouble());
  if(arrange&&!QetLanguages16::hiddenMember21(data,text->languageId16())&&!text->diagram()->isReadOnly()&&e.value("enabled").toBool()&&v.value("auto",false).toBool()){
   auto rule=QetPlacement16::rule(v);rule.automatic=true;auto result=QetPlacement16::place(text,owner(text),rule,text->diagram()->border_and_titleblock.insideBorderRect(),false);
   // Keep the previous location when no collision-free candidate exists.
   if(result.resolved){text->setPos(result.position);v["x"]=text->pos().x();v["y"]=text->pos().y();auto variants=target.value("variants").toMap();variants[lang]=v;target["variants"]=variants;entries[effective]=target;}
  }
 }
 data["entries"]=entries;project->setLanguageData(data);for(auto *page:project->diagrams())page->update();return data;
}
inline QStringList review(QETProject *project){QStringList issues;const auto data=project->languageData();QString lang=QetLanguages16::activeLanguage(data);auto entries=data.value("entries").toMap();for(auto it=entries.cbegin();it!=entries.cend();++it){auto e=it.value().toMap();if(!e.value("enabled").toBool())continue;auto v=QetLanguages16::variant(data,it.key());if(lang!=QetLanguages16::sourceLanguage(data)&&QetLanguages16::blockId21(data,it.key()).isEmpty()&&!QetLanguages16::hasTranslation(data,it.key(),lang))issues<<"["+it.key()+"] "+e.value("context").toString()+": "+QObject::tr("Missing or stale %1 translation; source text shown.").arg(lang);}for(auto *t:texts(project)){auto e=entries.value(t->languageId16()).toMap();if(!e.value("enabled").toBool()||QetLanguages16::hiddenMember21(data,t->languageId16()))continue;auto v=QetLanguages16::variant(data,t->languageId16());QFont checkFont=t->font();if(!v.value("font").toString().isEmpty())checkFont.fromString(v.value("font").toString());QFontMetrics metrics(checkFont);for(auto c:t->displayedText16().toUcs4())if(c>127&&!QChar::isSpace(c)&&!metrics.inFontUcs4(c)){issues<<"["+t->languageId16()+"] "+e.value("context").toString()+": "+QObject::tr("Verify font coverage for this language; choose an installed language font if glyphs are missing.");break;}QetPlacement16::Rule r;r.side="current";r.writtenOnly23=true;r.automatic=false;r.locked=true;r.allowOverlap=v.value("allowOverlap").toBool();r.maxLines=v.value("maxLines",0).toInt();auto result=QetPlacement16::place(t,owner(t),r,t->diagram()->border_and_titleblock.insideBorderRect(),false);for(const auto &s:result.issues)issues<<"["+t->languageId16()+"] "+e.value("context").toString()+": "+(lang==QetLanguages16::sourceLanguage(data)?QObject::tr("Original layout: "):QString())+s;}return issues;}
struct Position {QPointer<DiagramTextItem> item;QPointF pos;};
inline QList<Position> positions(QETProject *project){QList<Position> out;for(auto *t:texts(project))out<<Position{t,t->pos()};return out;}
inline void restorePositions(const QList<Position>&positions){for(const auto &p:positions)if(p.item)p.item->setPos(p.pos);}
class Change:public QUndoCommand{QPointer<QETProject> project;QVariantMap before,after;QList<Position> oldPos,newPos;public:Change(QETProject*p,const QVariantMap&b,const QVariantMap&a,const QList<Position>&bp,const QList<Position>&ap,QUndoCommand *parent=nullptr):QUndoCommand(QObject::tr("Change project language and text layout"),parent),project(p),before(b),after(a),oldPos(bp),newPos(ap){}void redo()override{if(project){apply(project,after,false);restorePositions(newPos);}}void undo()override{if(project){apply(project,before,false);restorePositions(oldPos);}}};
