 void filterEntries25(){
  if(loading)return;
  saveRule();
  const bool checkedOnly=entryFilter25->currentData().toBool();
  const int previousRow=grid->currentRow();
  int visible=0,next=-1,last=-1;
  QSignalBlocker blocker(grid);
  for(int row=0;row<grid->rowCount();++row){
   const bool hidden=checkedOnly&&grid->item(row,0)->checkState()!=Qt::Checked;
   grid->setRowHidden(row,hidden);
   if(hidden){
    // Hidden selections must not receive actions intended for visible rows.
    grid->selectionModel()->select(grid->model()->index(row,0),QItemSelectionModel::Deselect|QItemSelectionModel::Rows);
   }else{
    ++visible;last=row;if(next<0&&row>=previousRow)next=row;
   }
  }
  if(previousRow<0||grid->isRowHidden(previousRow)){
   const int row=next>=0?next:last;
   if(row<0){grid->clearSelection();grid->setCurrentCell(-1,-1);}
   else{
    const auto command=grid->selectionModel()->hasSelection()?QItemSelectionModel::NoUpdate:QItemSelectionModel::ClearAndSelect;
    grid->setCurrentCell(row,3,command);
   }
  }
  entryCount25->setText(visible==0&&checkedOnly
   ?tr("No entries checked. Choose All entries to select texts for translation.")
   :tr("Showing %1 of %2 entries").arg(visible).arg(grid->rowCount()));
  loadRule();
 }

